"use client";

import { useEffect, useState } from "react";
import { Pencil, Plus, Search, Trash2 } from "lucide-react";

const labels: Record<string, string> = { users: "Users", accounts: "Accounts", transactions: "Transactions", cards: "Cards", crypto: "Crypto holdings", news: "News and content" };
const fields: Record<string, string[]> = { users: ["name", "role"], accounts: ["status", "type"], transactions: ["status", "description"], cards: ["status", "cardHolder"], crypto: ["asset"], news: ["title", "excerpt", "body", "status"] };

export default function AdminResourceManager() {
  const [resource, setResource] = useState("users"); const [items, setItems] = useState<any[]>([]); const [query, setQuery] = useState(""); const [draft, setDraft] = useState<any>(null); const [notice, setNotice] = useState("");
  async function load() { const response = await fetch(`/api/admin/resources/${resource}`); const data = await response.json(); setItems(response.ok ? data.items : []); }
  useEffect(() => { load(); }, [resource]);
  async function save() { const response = await fetch(`/api/admin/resources/${resource}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify(draft) }); setNotice(response.ok ? "Record updated." : "Unable to update record."); setDraft(null); if (response.ok) load(); }
  async function remove(id: string) { if (!window.confirm("Delete this record?")) return; const response = await fetch(`/api/admin/resources/${resource}`, { method: "DELETE", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ id }) }); const data = await response.json(); setNotice(response.ok ? "Record deleted." : data.error || "Unable to delete record."); if (response.ok) load(); }
  const filtered = items.filter((item) => JSON.stringify(item).toLowerCase().includes(query.toLowerCase()));
  return <div className="space-y-5"><div className="flex flex-col gap-3 rounded-2xl border border-slate-800 bg-slate-900 p-4 sm:flex-row"><select value={resource} onChange={(e) => setResource(e.target.value)} className="rounded-lg border border-slate-800 bg-slate-950 px-3 py-2.5 text-xs text-white">{Object.entries(labels).map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select><label className="relative flex-1"><Search size={14} className="absolute left-3 top-3 text-slate-500" /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search records" className="w-full rounded-lg border border-slate-800 bg-slate-950 py-2.5 pl-9 pr-3 text-xs text-white" /></label>{resource === "news" && <button onClick={() => setDraft({ title: "", excerpt: "", body: "", status: "DRAFT" })} className="inline-flex items-center justify-center gap-1 rounded-lg bg-red-500 px-4 py-2 text-xs font-semibold text-white"><Plus size={14} /> New article</button>}</div>{notice && <p role="status" className="text-xs text-slate-400">{notice}</p>}<div className="overflow-x-auto rounded-2xl border border-slate-800 bg-slate-900 shadow-xl"><table className="w-full text-left"><thead><tr className="border-b border-slate-800 text-[10px] uppercase tracking-wider text-slate-500"><th className="px-4 py-3">Record</th><th className="px-4 py-3">Details</th><th className="px-4 py-3 text-right">Actions</th></tr></thead><tbody className="divide-y divide-slate-800">{filtered.map((item) => <tr key={item.id} className="text-xs text-slate-300"><td className="max-w-64 px-4 py-4"><p className="truncate font-mono text-indigo-300">{item.title || item.name || item.email || item.asset || item.reference || item.id}</p><p className="mt-1 text-[10px] text-slate-500">{item.id}</p></td><td className="max-w-96 px-4 py-4 text-slate-400">{item.status || item.role || item.description || item.merchant || item.user?.email || `${item.quantity || ""} ${item.asset || ""}`}</td><td className="px-4 py-4 text-right"><button onClick={() => setDraft(item)} className="mr-3 inline-flex items-center gap-1 text-indigo-300"><Pencil size={13} /> Edit</button>{resource !== "transactions" && <button onClick={() => remove(item.id)} className="inline-flex items-center gap-1 text-red-300"><Trash2 size={13} /> Delete</button>}</td></tr>)}{!filtered.length && <tr><td colSpan={3} className="px-4 py-12 text-center text-xs text-slate-500">No records found.</td></tr>}</tbody></table></div>{draft && <div className="fixed inset-0 z-40 flex items-center justify-center bg-black/70 px-5"><div className="w-full max-w-lg rounded-2xl border border-slate-700 bg-slate-900 p-6"><h2 className="text-base font-semibold text-white">Edit {labels[resource]}</h2><div className="mt-4 space-y-3">{(fields[resource] || []).map((field) => <label key={field} className="block text-xs text-slate-400">{field}<textarea rows={field === "body" ? 5 : 2} value={draft[field] || ""} onChange={(e) => setDraft({ ...draft, [field]: e.target.value })} className="mt-1 w-full rounded-lg border border-slate-800 bg-slate-950 px-3 py-2 text-xs text-white" /></label>)}</div><div className="mt-5 flex justify-end gap-2"><button onClick={() => setDraft(null)} className="rounded-lg border border-slate-700 px-4 py-2 text-xs text-slate-300">Cancel</button><button onClick={save} className="rounded-lg bg-red-500 px-4 py-2 text-xs font-semibold text-white">Save changes</button></div></div></div>}</div>;
}